INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q6', 'GATE', 'CS', '', 2025, '2', 6, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Based only on the conversation below, identify the logically correct inference: "Even if I had known that you were in the hospital, I would not have gone there to see you", Ramya told Josephine.', ARRAY[ARRAY['Ramya knew that Josephine was in the hospital.'], ARRAY['Ramya did not know that Josephine was in the hospital.'], ARRAY['Ramya and Josephine were once close friends; but now, they are not.'], ARRAY['Josephine was in the hospital due to an injury to her leg.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
