INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q26', 'GATE', 'CS', '', 2025, '2', 26, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Processes 1, 2, 3, 4 arrive in that order at times 0, 1, 2, and 8 milliseconds respectively, and have execution times of 10, 13, 6, and 9 milliseconds respectively. Shortest Remaining Time First (SRTF) algorithm is used as the CPU scheduling policy. Ignore context switching times. Which ONE of the following correctly gives the average turnaround time of the four processes in milliseconds?', ARRAY[ARRAY['22'], ARRAY['15'], ARRAY['37'], ARRAY['19']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q27', 'GATE', 'CS', '', 2025, '2', 27, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'An audit of a banking transactions system has found that on an earlier occasion, two joint holders of account attempted simultaneous transfers of Rs. 10000 each from account to account . Both transactions read the same value, Rs. 11000, as the initial balance in and were allowed to go through. was credited Rs. 10000 twice. was debited only once and ended up with a balance of Rs. 1000. Which of the following properties is/are certain to have been violated by the system?', ARRAY[ARRAY['Atomicity'], ARRAY['Consistency'], ARRAY['Isolation'], ARRAY['Durability']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q28', 'GATE', 'CS', '', 2025, '2', 28, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following is/are part of an Instruction Set Architecture of a processor?', ARRAY[ARRAY['The size of the cache memory'], ARRAY['The clock frequency of the processor'], ARRAY['The number of cache memory levels'], ARRAY['The total number of registers']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q29', 'GATE', 'CS', '', 2025, '2', 29, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following statements regarding Breadth First Search (BFS) and Depth First Search (DFS) on an undirected simple graph G is/are TRUE?', ARRAY[ARRAY['A DFS tree of is a Shortest Path tree of .'], ARRAY['Every non-tree edge of G with respect to a DFS tree is a forward/back edge.'], ARRAY['If (, ) is a non-tree edge of G with respect to a BFS tree, then the distances from'], ARRAY['Both BFS and DFS can be used to find the connected components of G.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2025_s2_q30', 'GATE', 'CS', '', 2025, '2', 30, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the two lists List I and List II given below: List I List II (i) Context free languages (a) Closed under union (ii) Recursive languages (b) Not closed under complementation (iii) Regular languages (c) Closed under intersection For matching of items in List I with those in List II, which of the following option(s) is/are CORRECT?', ARRAY[ARRAY['(i) � (a), (ii) � (b), and (iii) � (c)'], ARRAY['(i) � (b), (ii) � (a), and (iii) � (c)'], ARRAY['(i) � (b), (ii) � (c), and (iii) � (a)'], ARRAY['(i) � (a), (ii) � (c), and (iii) � (b)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
